PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT DISTINCT ?italianWord WHERE {
  GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord ; lila:hasPOS lila:noun ; lila:hasGender lila:feminine . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  FILTER(REGEX(STR(?italianWord), "ezza$"))
}

