PREFIX elita: <http://w3id.org/elita/>

SELECT ?pos (STRAFTER(STR(?pos), "lila/") AS ?posText) (COUNT(DISTINCT ?italianLemma) AS ?count) WHERE {
  GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord ; lila:hasPOS ?pos . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
