PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?italianWord (MAX(?polarityValue) AS ?maxPolarity) WHERE {
  { SELECT (MAX(xsd:float(?refValue)) AS ?refPolarity) WHERE {
      ?refLemma ontolex:writtenRep ?refWord . FILTER(STR(?refWord) = "appartenenza")
      ?refPolarityEntry ontolex:canonicalForm ?refLemma ; marl:hasPolarity ?refValueClass ; marl:hasPolarityValue ?refValueRaw . BIND(xsd:float(?refValueRaw) AS ?refValue)
  } }
  GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord ; lila:hasPOS lila:noun . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  ?emotionEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion elita:Fiducia .
  ?polarityEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarity ?polarityClass ; marl:hasPolarityValue ?rawValue .
  BIND(xsd:float(?rawValue) AS ?polarityValue)
  FILTER(?polarityValue > ?refPolarity)
}
GROUP BY ?italianWord

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?italianLemma) AS ?count) WHERE {
  GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  { ?emotionEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion elita:Disgusto . }
  UNION
  { ?polarityEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarity ?polarityValueClass ; marl:hasPolarityValue ?polarityValueRaw . BIND(xsd:float(?polarityValueRaw) AS ?polarityValue) FILTER(?polarityValue < -0.9) }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>

SELECT DISTINCT ?italianWord WHERE {
  GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord ; lila:hasPOS lila:adjective . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  ?trustEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion elita:Fiducia .
  ?surpriseEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion elita:Sorpresa .
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>

SELECT DISTINCT ?partWord ?italianWord WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?seed ontolex:canonicalForm [ ontolex:writtenRep ?seedWr ] ; ontolex:sense ?seedSense .
    FILTER(STR(?seedWr) = "autoveicolo")
    ?midSense lexinfo:partMeronym ?seedSense .
    ?relSense lexinfo:partMeronym ?midSense .
    ?partWord ontolex:sense ?relSense ; ontolex:canonicalForm [ ontolex:writtenRep ?italianWord ] .
  }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>

SELECT DISTINCT ?hypernymWord ?italianWord WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?seed ontolex:canonicalForm [ ontolex:writtenRep ?seedWr ] ; ontolex:sense ?seedSense .
    FILTER(STR(?seedWr) = "salmone")
    ?seedSense lexinfo:hyponym ?midSense .
    ?midSense lexinfo:hyponym ?relSense .
    ?hypernymWord ontolex:sense ?relSense ; ontolex:canonicalForm [ ontolex:writtenRep ?italianWord ] .
  }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?italianWord ?polarityValue WHERE {
  GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord ; lila:hasPOS lila:noun . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  ?polarityEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarity ?polarityValueClass ; marl:hasPolarityValue ?polarityValueRaw . BIND(xsd:float(?polarityValueRaw) AS ?polarityValue)
  FILTER(?polarityValue < -0.8)
  FILTER NOT EXISTS { ?emotionEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion ?emotion . }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>

SELECT DISTINCT ?italianWord WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?seed ontolex:canonicalForm [ ontolex:writtenRep ?seedWr ] ; ontolex:sense ?seedSense .
    FILTER(STR(?seedWr) = "frutto")
    ?seedSense lexinfo:hypernym ?relSense .
    ?relWord ontolex:sense ?relSense .
  }
  ?relWord ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  FILTER NOT EXISTS {
    ?sicEntryIt ontolex:canonicalForm ?italianLemma ; vartrans:translatableAs ?sicEntry .
    ?sicEntry ontolex:canonicalForm ?sicilianLemma .
    ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
  }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?italianWord WHERE {
  GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord ; lila:hasPOS lila:adverb . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  ?polarityEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarity ?sentixValueClass ; marl:hasPolarityValue ?sentixValueRaw . BIND(xsd:float(?sentixValueRaw) AS ?sentixValue)
  GRAPH <http://w3id.org/elita> {
    ?elitaEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarityValue ?elitaRaw .
  }
  BIND(xsd:float(?elitaRaw) AS ?elitaValue)
  FILTER((?sentixValue > 0 && ?elitaValue < 0) || (?sentixValue < 0 && ?elitaValue > 0))
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (AVG(?emotionCount) AS ?avgEmotions) WHERE {
  { SELECT ?italianLemma (COUNT(DISTINCT ?emotion) AS ?emotionCount) WHERE {
      GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord ; lila:hasPOS lila:adjective . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
      ?emotionEntry ontolex:canonicalForm ?italianLemma ; elita:HasEmotion ?emotion . ?emotion rdfs:label ?emotionLabel .
  } GROUP BY ?italianLemma }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?italianWord (MAX(?polarityValue) AS ?maxPolarity) WHERE {
  { SELECT (MAX(?refValue) AS ?refPolarity) WHERE {
      ?refLemma ontolex:writtenRep ?refWord . FILTER(STR(?refWord) = "studiare")
      ?refPolarityEntry ontolex:canonicalForm ?refLemma ; marl:hasPolarity ?refValueClass ; marl:hasPolarityValue ?refValueRaw . BIND(xsd:float(?refValueRaw) AS ?refValue)
  } }
  GRAPH <http://liita.it/data> { ?italianLemma a ?italianLemmaType ; ontolex:writtenRep ?italianWord ; lila:hasPOS lila:verb . FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  ?polarityEntry ontolex:canonicalForm ?italianLemma ; marl:hasPolarity ?polarityValueClass ; marl:hasPolarityValue ?polarityValueRaw . BIND(xsd:float(?polarityValueRaw) AS ?polarityValue)
